async function saveRecovered(ev){
 ev.preventDefault();
 const form=$('recoverForm'),save=$('recoverSave'),status=$('recoverStatus');if(!form||!save)return;
 const data=new FormData(form),state=String(data.get('state')||'delivered');
 const start=new Date(String(data.get('acceptedAt')||'')),finish=new Date(String(data.get('finishedAt')||''));
 if(!Number.isFinite(start.getTime())||(state==='delivered'&&(!Number.isFinite(finish.getTime())||finish<start))){
  if(status)status.textContent='Check the order start and completion time.';return
 }
 const body={clientId:recoverRetryId,merchant:String(data.get('merchant')||'').trim(),payout:Number(data.get('payout')),state,
  acceptedAt:start.toISOString(),finishedAt:state==='delivered'?finish.toISOString():null,
  miles:data.get('miles')===''?null:Number(data.get('miles')),
  etaMinutes:data.get('etaMinutes')===''?null:Number(data.get('etaMinutes'))};
 save.disabled=true;if(status)status.textContent='Saving missed order…';
 try {
  const result=await api('/api/recover',{method:'POST',body:JSON.stringify(body)});
  if(!result.ok)throw Error(result.error||'Order was not saved.');
  $('recoverDialog')?.close();recoverRetryId=null;
  await refreshData();
  if(state!=='delivered'){if(status)status.textContent='Recovered order ready to advance.'}
 }catch(error){if(status)status.textContent=error.message}
 finally{save.disabled=false}
}
